(()=>{'use strict';const BASE=<?= json_encode(BASE_URL,JSON_UNESCAPED_SLASHES) ?>,API=BASE+'/api/scheduling/substitute-assignment.php',PREFILL={schedule:<?= $prefillSchedule ?>,assignment:<?= $prefillAssignment ?>};const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const S={page:1,max:1,data:null,class:null,date:null,candidates:[],selected:null,validation:null,saved:null};
function showAlert(m){$('satAlert').classList.toggle('d-none',!m);$('satAlert').querySelector('span').textContent=m||'';if(m)scrollTo({top:0,behavior:'smooth'})}async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json'},...opt});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Request failed.');return d}function go(n){if(n>S.max)return;S.page=n;document.querySelectorAll('.sat-page').forEach(x=>x.classList.toggle('d-none',+x.dataset.page!==n));document.querySelectorAll('#satSteps li').forEach((x,i)=>{x.classList.toggle('active',i+1===n);x.classList.toggle('done',i+1<n)});showAlert('');scrollTo({top:0,behavior:'smooth'})}function unlock(n){S.max=Math.max(S.max,n);go(n)}
function badge(t){const c={Pending:'amber',Assigned:'blue',Ongoing:'purple',Completed:'green',Cancelled:'red',Validated:'green',Published:'blue',Eligible:'green',Conflict:'red','Not configured':'amber'}[t]||'gray';return`<span class="sat-badge ${c}">${esc(t)}</span>`}function fmt(v){return v?new Date(v+'T00:00:00').toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}):'—'}function dl(a){return`<dl class="sat-dl">${a.map(x=>`<dt>${esc(x[0])}</dt><dd>${x[2]?x[1]:esc(x[1]??'—')}</dd>`).join('')}</dl>`}function nextDate(day){const ds=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],d=new Date();let add=(ds.indexOf(day)-d.getDay()+7)%7;if(!add)add=7;d.setDate(d.getDate()+add);return d.toISOString().slice(0,10)}
function filters(){return{search:$('filterSearch').value,program:$('filterProgram').value,section:$('filterSection').value,status:$('filterStatus').value,from:$('filterFrom').value,to:$('filterTo').value}}function renderDashboard(){const s=S.data.stats,icons={Pending:'clock-exclamation',Assigned:'user-check',Ongoing:'progress-check',Completed:'circle-check',Cancelled:'circle-x'};$('satMetrics').innerHTML=Object.keys(icons).map(k=>`<div class="sat-metric ${k.toLowerCase()}"><i class="ti ti-${icons[k]}"></i><div><b>${s[k]||0}</b><small>${k}</small></div></div>`).join('');$('classRows').innerHTML=S.data.classes.length?S.data.classes.map(c=>`<tr><td><b>${esc(c.subject_code)} · ${esc(c.subject_name)}</b><br><small>${esc(c.section_code)} · ${esc(c.program)}</small></td><td>${esc(c.original_teacher)}</td><td>${esc(c.day_of_week)}<br><small>${esc(c.start_time)}–${esc(c.end_time)}</small></td><td>${esc(c.room_code||'Unassigned')}</td><td>${badge(c.status)}</td><td><button class="btn btn-sm btn-primary" data-class="${c.id}"><i class="ti ti-user-plus"></i> Assign</button></td></tr>`).join(''):'<tr><td colspan="6" class="sat-empty"><i class="ti ti-calendar-off d-block fs-3 mb-2"></i>No validated or published classes match these filters.</td></tr>';$('assignmentRows').innerHTML=S.data.records.length?S.data.records.map(r=>`<tr><td><b>${esc(r.reference_no||'Pending')}</b><br><small>${esc(r.original_teacher)}</small></td><td>${esc(r.subject_code)} · ${esc(r.section_code)}<br><small>${esc(r.substitute_teacher||'Unassigned')}</small></td><td>${fmt(r.absence_date)}</td><td>${badge(r.status)}</td><td><button class="btn btn-sm btn-outline-primary" data-view="${r.id}"><i class="ti ti-eye"></i></button></td></tr>`).join(''):'<tr><td colspan="5" class="sat-empty"><i class="ti ti-clipboard-off d-block fs-3 mb-2"></i>No assignments recorded.</td></tr>'}
async function loadDashboard(){try{const p=new URLSearchParams({action:'dashboard',...filters()});const d=await api(API+'?'+p);const first=!S.data;S.data=d;if(first){d.programs.forEach(v=>$('filterProgram').insertAdjacentHTML('beforeend',`<option>${esc(v)}</option>`));d.sections.forEach(v=>$('filterSection').insertAdjacentHTML('beforeend',`<option>${esc(v)}</option>`))}renderDashboard();if(first&&PREFILL.schedule){const c=d.classes.find(x=>x.id===PREFILL.schedule);if(c)selectClass(c)}if(first&&PREFILL.assignment)viewAssignment(PREFILL.assignment)}catch(e){showAlert(e.message)}}
function selectClass(c){S.class=c;S.date=nextDate(c.day_of_week);$('absenceDate').value=S.date;$('absenceEnd').value=S.date;$('absenceDay').textContent=c.day_of_week+' class occurrence';$('classSummary').innerHTML=dl([['Subject',c.subject_code+' · '+c.subject_name],['Program',c.program],['Section',c.section_code],['Original faculty',c.original_teacher],['Schedule',c.day_of_week+' · '+c.start_time+'–'+c.end_time],['Room',c.room_code||'Unassigned'],['Class status',badge(c.status),true]]);unlock(2)}function absencePayload(action,withTeacher=true){return{action,schedule_entry_id:S.class?.id,substitute_teacher_id:withTeacher?S.selected?.teacher?.id||0:0,absence_date:$('absenceDate').value,absence_end_date:$('absenceEnd').value,duration_label:$('durationLabel').value,reason:$('absenceReason').value,remarks:$('absenceRemarks').value}}
function validateAbsence(){if(!$('absenceDate').value||!$('absenceEnd').value||!$('absenceReason').value){showAlert('Absence date, end date, and reason are required.');return false}const day=new Date($('absenceDate').value+'T00:00:00').toLocaleDateString('en-US',{weekday:'long'});if(day!==S.class.day_of_week){showAlert('The absence date must fall on '+S.class.day_of_week+' for this class.');return false}if($('absenceEnd').value<$('absenceDate').value){showAlert('Leave end date cannot be before the absence date.');return false}return true}
async function saveDraft(withTeacher=true){if(!validateAbsence())return;try{const d=await api(API,{method:'POST',body:JSON.stringify(absencePayload('save_draft',withTeacher))});showAlert('');return d}catch(e){showAlert(e.message)}}
async function loadCandidates(){if(!validateAbsence())return;try{S.date=$('absenceDate').value;const p=new URLSearchParams({action:'candidates',schedule_entry_id:S.class.id,absence_date:S.date,search:$('candidateSearch').value,department:$('candidateDepartment').value});const d=await api(API+'?'+p);S.candidates=d.candidates;const depts=[...new Set(d.candidates.map(x=>x.teacher?.department).filter(Boolean))];if($('candidateDepartment').options.length===1)depts.forEach(v=>$('candidateDepartment').insertAdjacentHTML('beforeend',`<option>${esc(v)}</option>`));$('candidateClass').innerHTML=`<b><i class="ti ti-school me-1"></i>${esc(S.class.subject_code)} · ${esc(S.class.subject_name)} · ${esc(S.class.section_code)}</b><p>${fmt(S.date)} (${esc(S.class.day_of_week)}) · ${esc(S.class.start_time)}–${esc(S.class.end_time)} · ${esc(S.class.room_code||'Room unassigned')} · absent: ${esc(S.class.original_teacher)}</p>`;renderCandidates();unlock(3)}catch(e){showAlert(e.message)}}
function renderCandidates(){const only=$('eligibleOnly').checked,rows=S.candidates.filter(x=>!only||x.eligible);$('candidateCount').textContent=rows.length+' candidate(s) · qualification '+(S.data.qualification_configured?'configured':'not configured')+' · availability '+(S.data.availability_configured?'configured':'not configured');$('candidateRows').innerHTML=rows.length?rows.map((x,i)=>{const t=x.teacher,recommended=i===0&&x.eligible;return`<tr><td><b>${esc(t.full_name)}</b><br><small>${esc(t.employee_no||'No employee number')}</small></td><td>${esc(t.department||'—')}</td><td>${esc(t.specialization)}</td><td>${t.current_load_units}/${t.max_load_units||'—'}</td><td>${badge(t.availability==='Unavailable'?'Conflict':t.availability)}</td><td><div class="sat-fit">${recommended?'<span class="sat-badge green"><i class="ti ti-sparkles"></i> Recommended</span>':''}${badge(x.eligible?'Eligible':'Conflict')}<span class="sat-badge blue">Score ${x.score}</span></div></td><td><button class="btn btn-sm btn-outline-primary me-1" data-schedule="${t.id}"><i class="ti ti-calendar"></i></button><button class="btn btn-sm btn-primary" data-candidate="${t.id}" ${x.eligible?'':'disabled'}>Select</button></td></tr>`}).join(''):'<tr><td colspan="7" class="sat-empty"><i class="ti ti-user-search d-block fs-3 mb-2"></i>No candidates match this view.</td></tr>'}
function selectCandidate(id){S.selected=S.candidates.find(x=>x.teacher.id===id);const x=S.selected,t=x.teacher;$('selectedCandidate').classList.remove('d-none');$('selectedCandidate').innerHTML=`<i class="ti ti-user-check"></i><div><b>Selected: ${esc(t.full_name)}</b><p>${esc(t.department)} · ${esc(t.specialization)} · load ${t.current_load_units}/${t.max_load_units||'not configured'} · score ${x.score}</p><small>${esc(x.recommended_reasons.join(' · ')||'All critical checks passed')}</small></div>`;$('reviewNext').disabled=false}
async function teacherSchedule(id){try{const d=await api(API+'?'+new URLSearchParams({action:'teacher_schedule',teacher_id:id,date:S.date}));$('dialogTitle').innerHTML='<i class="ti ti-calendar-user"></i>Faculty Schedule';$('dialogSubtitle').textContent=d.day+' · '+fmt(d.date);$('dialogBody').innerHTML=d.schedule.length?d.schedule.map(x=>`<div class="sat-history-item"><b>${esc(x.start_time)}–${esc(x.end_time)} · ${esc(x.subject_code)} ${esc(x.section_code)}</b><p>${esc(x.room_code||'Room unassigned')} · ${esc(x.source)}</p></div>`).join(''):'<div class="sat-empty"><i class="ti ti-calendar-check d-block fs-3 mb-2"></i>No regular class recorded for this day.</div>';$('satOverlay').classList.remove('d-none')}catch(e){showAlert(e.message)}}
async function runValidation(){try{const d=await api(API,{method:'POST',body:JSON.stringify(absencePayload('validate'))});S.validation=d.validation;renderReview();unlock(4)}catch(e){showAlert(e.message)}}function renderReview(){const t=S.selected.teacher;$('reviewSummary').innerHTML=dl([['Class',S.class.subject_code+' · '+S.class.subject_name],['Section / room',S.class.section_code+' · '+(S.class.room_code||'Unassigned')],['Date / time',fmt(S.date)+' · '+S.class.start_time+'–'+S.class.end_time],['Absent faculty',S.class.original_teacher],['Reason',$('absenceReason').value],['Leave duration',$('durationLabel').value||fmt($('absenceDate').value)+' to '+fmt($('absenceEnd').value)],['Substitute',t.full_name],['Department',t.department],['Specialization',t.specialization],['Current load',t.current_load_units+' / '+(t.max_load_units||'not configured')]]);$('validationRows').innerHTML=S.validation.checks.map(c=>{const cls=!c.passed&&c.level==='critical'?'fail':c.level==='warning'?'warn':'pass',icon=cls==='fail'?'x':cls==='warn'?'alert-triangle':'check';return`<div class="sat-validation ${cls}"><i class="ti ti-${icon}"></i><div><b>${esc(c.label)}</b><small>${esc(c.detail)}</small></div>${badge(c.passed?'Passed':c.level==='warning'?'Review':'Failed')}</div>`}).join('');$('validationBanner').className='sat-validation-banner '+(S.validation.eligible?'pass':'fail');$('validationBanner').innerHTML=S.validation.eligible?'<i class="ti ti-shield-check me-1"></i>All critical checks passed. Final server-side validation will run again before saving.':'<i class="ti ti-shield-x me-1"></i>Critical validation failed. Choose another substitute.';$('confirmAssignment').disabled=!S.validation.eligible}
async function confirm(){const b=$('confirmAssignment'),old=b.innerHTML;b.disabled=true;b.innerHTML='<i class="ti ti-loader-2 ti-spin me-1"></i>Final Validation…';try{const d=await api(API,{method:'POST',body:JSON.stringify(absencePayload('confirm'))});S.saved=d.assignment;$('savedReference').textContent=d.assignment.reference_no;$('completeSummary').innerHTML=dl([['Class',d.assignment.subject_code+' · '+d.assignment.subject_name],['Section',d.assignment.section_code],['Absent faculty',d.assignment.original_teacher],['Substitute',d.assignment.substitute_teacher],['Date / time',fmt(d.assignment.absence_date)+' · '+d.assignment.start_time+'–'+d.assignment.end_time],['Room',d.assignment.room_code||'Unassigned'],['Status',badge(d.assignment.status),true]]);$('notificationSummary').innerHTML=`<b><i class="ti ti-bell-check me-1"></i>Notifications queued: ${d.notifications_queued}</b><p class="mb-0 mt-1">Substitute faculty, original faculty, affected section, and scheduling staff are included in the notification audit queue.</p>`;$('goConflict').href=BASE+'/modules/scheduling/pages/conflict-checker.php?source_type=Regular&record_id='+d.assignment.schedule_entry_id;unlock(5)}catch(e){showAlert(e.message)}finally{b.disabled=false;b.innerHTML=old}}
async function viewAssignment(id){try{const d=await api(API+'?action=assignment&id='+id),r=d.assignment;$('dialogTitle').innerHTML='<i class="ti ti-clipboard-text"></i>'+esc(r.reference_no||'Substitute Assignment');$('dialogSubtitle').textContent=r.status+' · '+fmt(r.absence_date);$('dialogBody').innerHTML=dl([['Class',r.subject_code+' · '+r.subject_name],['Section',r.section_code],['Original faculty',r.original_teacher],['Substitute',r.substitute_teacher||'Unassigned'],['Schedule',r.day_of_week+' · '+r.start_time+'–'+r.end_time],['Room',r.room_code||'Unassigned'],['Reason',r.reason],['Duration',r.duration_label||fmt(r.absence_date)+' to '+fmt(r.absence_end_date)],['Status',badge(r.status),true]])+`<h3 class="fs-6 mt-4"><i class="ti ti-history me-1"></i>History</h3>`+(d.history.length?d.history.map(h=>`<div class="sat-history-item"><b>${esc(h.action)} · ${esc(h.to_status||h.from_status||'')}</b><p>${esc(h.detail)}</p><small>${esc(h.changed_by_name)} · ${esc(h.changed_at)}</small></div>`).join(''):'<p class="text-muted small">No history entries.</p>')+statusActions(r);$('satOverlay').classList.remove('d-none')}catch(e){showAlert(e.message)}}function statusActions(r){const next={Pending:['Assigned','Cancelled'],Assigned:['Ongoing','Completed','Cancelled'],Ongoing:['Completed','Cancelled'],Completed:[],Cancelled:['Pending']}[r.status]||[];return next.length?`<div class="d-flex flex-wrap gap-2 mt-3">${next.map(x=>`<button class="btn btn-sm btn-outline-primary" data-status-id="${r.id}" data-status="${x}"><i class="ti ti-progress-check me-1"></i>Mark ${x}</button>`).join('')}</div>`:''}
async function updateStatus(id,status){try{await api(API,{method:'POST',body:JSON.stringify({action:'update_status',id,status})});$('satOverlay').classList.add('d-none');await loadDashboard()}catch(e){showAlert(e.message)}}function showAllHistory(){const rows=S.data.records;$('dialogTitle').innerHTML='<i class="ti ti-history"></i>Substitute Assignment History';$('dialogSubtitle').textContent='Open any assignment for its complete audit trail.';$('dialogBody').innerHTML=rows.length?rows.map(r=>`<div class="sat-history-item"><b>${esc(r.reference_no||'Pending')} · ${esc(r.status)}</b><p>${esc(r.subject_code)} ${esc(r.section_code)} · ${esc(r.original_teacher)} → ${esc(r.substitute_teacher||'Unassigned')}</p><small>${fmt(r.absence_date)} · updated ${esc(r.updated_at)}</small></div>`).join(''):'<div class="sat-empty">No assignment history yet.</div>';$('satOverlay').classList.remove('d-none')}
document.addEventListener('click',e=>{const g=e.target.closest('[data-go]');if(g)go(+g.dataset.go);const b=e.target.closest('[data-back]');if(b)go(+b.dataset.back);const c=e.target.closest('[data-class]');if(c)selectClass(S.data.classes.find(x=>x.id===+c.dataset.class));const v=e.target.closest('[data-view]');if(v)viewAssignment(+v.dataset.view);const q=e.target.closest('[data-candidate]');if(q)selectCandidate(+q.dataset.candidate);const sc=e.target.closest('[data-schedule]');if(sc)teacherSchedule(+sc.dataset.schedule);const st=e.target.closest('[data-status-id]');if(st)updateStatus(+st.dataset.statusId,st.dataset.status)});
document.addEventListener('DOMContentLoaded',loadDashboard);$('applyFilters').onclick=loadDashboard;$('saveEarlyDraft').onclick=()=>saveDraft(false);$('findSubstitutes').onclick=loadCandidates;$('runCandidateFilter').onclick=loadCandidates;$('eligibleOnly').onchange=renderCandidates;$('autoSuggest').onclick=()=>{const x=S.candidates.find(x=>x.eligible);if(x)selectCandidate(x.teacher.id);else showAlert('No eligible substitute is available for this class time.')};$('reviewNext').onclick=runValidation;$('recheckSubstitute').onclick=runValidation;$('saveReviewDraft').onclick=()=>saveDraft(true);$('confirmAssignment').onclick=confirm;$('satHistory').onclick=showAllHistory;$('satPrint').onclick=()=>print();$('printSlip').onclick=()=>print();$('createAnother').onclick=()=>location.reload();$('backToList').onclick=()=>location.reload();$('viewSaved').onclick=()=>viewAssignment(S.saved.id);$('closeDialog').onclick=()=>$('satOverlay').classList.add('d-none');$('satOverlay').onclick=e=>{if(e.target===$('satOverlay'))$('satOverlay').classList.add('d-none')};$('absenceDate').onchange=()=>{$('absenceDay').textContent=new Date($('absenceDate').value+'T00:00:00').toLocaleDateString('en-US',{weekday:'long'})+' class occurrence';if($('absenceEnd').value<$('absenceDate').value)$('absenceEnd').value=$('absenceDate').value};
})();
</script>
